-- Create subscriptions table for validity management\nCREATE TABLE IF NOT EXISTS subscriptions (\n    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,\n    organization_id UUID REFERENCES organizations(id) ON DELETE CASCADE,\n    plan VARCHAR(50) NOT NULL DEFAULT 'trial',\n    status VARCHAR(20) NOT NULL DEFAULT 'active',\n    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\n    \n    CONSTRAINT unique_user_subscription UNIQUE(user_id),\n    CONSTRAINT valid_plan CHECK (plan IN ('trial', 'basic', 'pro', 'enterprise')),\n    CONSTRAINT valid_status CHECK (status IN ('active', 'expired', 'cancelled', 'suspended'))\n);\n\n-- Enable RLS\nALTER TABLE subscriptions ENABLE ROW LEVEL SECURITY;\n\n-- RLS Policies for subscriptions\nCREATE POLICY \"Users can view their own subscription\" ON subscriptions\n    FOR SELECT USING (auth.uid() = user_id);\n\nCREATE POLICY \"Service role can manage all subscriptions\" ON subscriptions\n    FOR ALL USING (auth.role() = 'service_role');\n\n-- Add indexes for better performance\nCREATE INDEX IF NOT EXISTS idx_subscriptions_user_id ON subscriptions(user_id);\nCREATE INDEX IF NOT EXISTS idx_subscriptions_organization_id ON subscriptions(organization_id);\nCREATE INDEX IF NOT EXISTS idx_subscriptions_expires_at ON subscriptions(expires_at);\nCREATE INDEX IF NOT EXISTS idx_subscriptions_status ON subscriptions(status);\n\n-- Function to automatically update updated_at\nCREATE OR REPLACE FUNCTION update_updated_at_column()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW;\nEND;\n$$ language plpgsql;\n\n-- Trigger to automatically update updated_at\nCREATE TRIGGER update_subscriptions_updated_at\n    BEFORE UPDATE ON subscriptions\n    FOR EACH ROW\n    EXECUTE FUNCTION update_updated_at_column();\n\n-- Function to check if subscription is expired\nCREATE OR REPLACE FUNCTION is_subscription_expired(user_uuid UUID)\nRETURNS BOOLEAN AS $$\nDECLARE\n    expiry_date TIMESTAMP WITH TIME ZONE;\nBEGIN\n    SELECT expires_at INTO expiry_date\n    FROM subscriptions\n    WHERE user_id = user_uuid AND status = 'active';\n    \n    IF expiry_date IS NULL THEN\n        RETURN TRUE; -- No subscription found, consider expired\n    END IF;\n    \n    RETURN expiry_date < now();\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\n-- Function to auto-expire subscriptions (can be run via cron)\nCREATE OR REPLACE FUNCTION auto_expire_subscriptions()\nRETURNS INTEGER AS $$\nDECLARE\n    expired_count INTEGER;\nBEGIN\n    UPDATE subscriptions \n    SET status = 'expired', updated_at = now()\n    WHERE status = 'active' AND expires_at < now();\n    \n    GET DIAGNOSTICS expired_count = ROW_COUNT;\n    RETURN expired_count;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER;\n\nCOMMIT;